import { sqliteTable, text, integer, index } from 'drizzle-orm/sqlite-core';

// Generated by Better Auth. Run `pnpm run auth:generate` to update these
// tables instead of editing them directly, such as after adding an auth plugin.

export const user = sqliteTable('user', {
  id: text('id').primaryKey(),
  name: text('name').notNull(),
  email: text('email').notNull().unique(),
  emailVerified: integer('email_verified', { mode: 'boolean' })
    .notNull()
    .default(false),
  image: text('image'),
  createdAt: integer('created_at', { mode: 'timestamp' })
    .notNull()
    .$defaultFn(() => new Date()),
  updatedAt: integer('updated_at', { mode: 'timestamp' })
    .notNull()
    .$defaultFn(() => new Date()),
  role: text('role'),
  banned: integer('banned', { mode: 'boolean' }).default(false),
  banReason: text('ban_reason'),
  banExpires: integer('ban_expires', { mode: 'timestamp' })
});

export const session = sqliteTable('session', {
  id: text('id').primaryKey(),
  expiresAt: integer('expires_at', { mode: 'timestamp' }).notNull(),
  token: text('token').notNull().unique(),
  createdAt: integer('created_at', { mode: 'timestamp' }).notNull(),
  updatedAt: integer('updated_at', { mode: 'timestamp' }).notNull(),
  ipAddress: text('ip_address'),
  userAgent: text('user_agent'),
  userId: text('user_id')
    .notNull()
    .references(() => user.id, { onDelete: 'cascade' }),
  impersonatedBy: text('impersonated_by')
});

export const account = sqliteTable('account', {
  id: text('id').primaryKey(),
  accountId: text('account_id').notNull(),
  providerId: text('provider_id').notNull(),
  userId: text('user_id')
    .notNull()
    .references(() => user.id, { onDelete: 'cascade' }),
  accessToken: text('access_token'),
  refreshToken: text('refresh_token'),
  idToken: text('id_token'),
  accessTokenExpiresAt: integer('access_token_expires_at', {
    mode: 'timestamp'
  }),
  refreshTokenExpiresAt: integer('refresh_token_expires_at', {
    mode: 'timestamp'
  }),
  scope: text('scope'),
  password: text('password'),
  createdAt: integer('created_at', { mode: 'timestamp' }).notNull(),
  updatedAt: integer('updated_at', { mode: 'timestamp' }).notNull()
});

export const verification = sqliteTable('verification', {
  id: text('id').primaryKey(),
  identifier: text('identifier').notNull(),
  value: text('value').notNull(),
  expiresAt: integer('expires_at', { mode: 'timestamp' }).notNull(),
  createdAt: integer('created_at', { mode: 'timestamp' }).$defaultFn(
    () => new Date()
  ),
  updatedAt: integer('updated_at', { mode: 'timestamp' }).$defaultFn(
    () => new Date()
  )
});

// Define your own tables below, then run `pnpm run db:generate` to create a
// migration. Migrations are applied to the production D1 database on publish.

export const workspaces = sqliteTable('crm_workspaces', {
  id: text('id').primaryKey(),
  ownerId: text('owner_id').notNull().unique().references(() => user.id, { onDelete: 'cascade' }),
  name: text('name').notNull(),
  createdAt: integer('created_at').notNull(),
});

// A shared record shape keeps the small CRM's search and activity links uniform.
export const crmRecords = sqliteTable('crm_records', {
  id: text('id').primaryKey(),
  workspaceId: text('workspace_id').notNull().references(() => workspaces.id, { onDelete: 'cascade' }),
  kind: text('kind', { enum: ['contact', 'company', 'deal', 'task'] }).notNull(),
  name: text('name').notNull(),
  email: text('email').notNull().default(''),
  phone: text('phone').notNull().default(''),
  role: text('role').notNull().default(''),
  website: text('website').notNull().default(''),
  industry: text('industry').notNull().default(''),
  tags: text('tags', { mode: 'json' }).$type<string[]>().notNull().default([]),
  status: text('status').notNull().default('lead'),
  value: integer('value').notNull().default(0),
  closeDate: text('close_date').notNull().default(''),
  dueDate: text('due_date').notNull().default(''),
  completed: integer('completed', { mode: 'boolean' }).notNull().default(false),
  companyId: text('company_id'),
  contactId: text('contact_id'),
  dealId: text('deal_id'),
  createdAt: integer('created_at').notNull(),
  updatedAt: integer('updated_at').notNull(),
}, (table) => [index('crm_records_workspace_kind').on(table.workspaceId, table.kind)]);

export const crmNotes = sqliteTable('crm_notes', {
  id: text('id').primaryKey(),
  workspaceId: text('workspace_id').notNull().references(() => workspaces.id, { onDelete: 'cascade' }),
  recordId: text('record_id').notNull().references(() => crmRecords.id, { onDelete: 'cascade' }),
  body: text('body').notNull(),
  author: text('author').notNull(),
  createdAt: integer('created_at').notNull(),
}, (table) => [index('crm_notes_workspace_record').on(table.workspaceId, table.recordId)]);

export const crmActivities = sqliteTable('crm_activities', {
  id: text('id').primaryKey(),
  workspaceId: text('workspace_id').notNull().references(() => workspaces.id, { onDelete: 'cascade' }),
  recordId: text('record_id'),
  message: text('message').notNull(),
  type: text('type').notNull(),
  author: text('author').notNull(),
  createdAt: integer('created_at').notNull(),
}, (table) => [index('crm_activities_workspace_date').on(table.workspaceId, table.createdAt)]);
